import{_ as n,l as r,o as e,c as l,v as i,p as s,x as t,d as m,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Gemini 原生多模态","description":"","frontmatter":{"title":"Gemini 原生多模态","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/gemini-native-mm.md","filePath":"llm/gemini-native-mm.md","lastUpdated":1789023840000}'),p={name:"llm/gemini-native-mm.md"};function d(A,a,c,g,u,M){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="gemini-原生多模态" tabindex="-1">Gemini 原生多模态 <a class="header-anchor" href="#gemini-原生多模态" aria-label="Permalink to &quot;Gemini 原生多模态&quot;">​</a></h1><div class="epigraph"><p>Gemini 从一开始就在图、音、视频与文本上联合训练，目标是每个模态上都能打到专有系统的水平，并且在同一条交错序列里做跨模态推理，而不是先训语言模型再把视觉当外挂。</p><footer>—— Gemini Team，Gemini: A Family of Highly Capable Multimodal Models，arXiv:2312.11805</footer></div><p>Google 2023 年 12 月的 Gemini 1.0 报告把家族写成 <strong>Ultra / Pro / Nano</strong>，上下文 <strong>32768</strong>，输入为文本与交错的自然图、图表、截屏、PDF、视频帧与音频，输出为文本，并可用离散图像 token 出图。视觉编码谱系写明受 Flamingo、CoCa、PaLI 启发，但<strong>模型从一开始就是多模态</strong>，不是冻结文本 LLM 再插交叉层。Nano 给出参数：蒸馏得到 <strong>1.8B / 3.25B</strong>，4-bit 部署。Ultra / Pro 的层数与 MoE 结构未公开。本篇只写 1.0 报告里的「原生」主张与可引用评测口径；Gemini 1.5（arXiv:2403.05530）的百万上下文与稀疏专家是后文，不把 1.5 的窗口写进 1.0 的 32K。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2023 年的多模态产品多数是「强文本模型 + 视觉适配器」：Flamingo 冻 LLM，GPT-4V 的公开技术细节不足以当配方，开源 LLaVA 明确是后接。这条路的风险是跨模态推理浅——模型会描述图，却难以在同一条上下文里把草算笔迹、口播和表格对齐成一步推导。音频若先 ASR 成字再进 LLM，重音、重叠、未成词的线索被丢掉。视频若只抽一帧，时间推理变成看图。</p><p>原生多模态要回答的是：联合训练会不会变成「样样稀松」？报告用专有对照表主张不会：Ultra 在他们列出的 32 项里 30 项当时领先，20 项多模态基准全部刷新，并第一次把 MMLU 推到「人类专家」叙事（见下）。问题从「要不要外挂」换成「联合训练如何编码各模态、如何证明单模态没有塌」。</p><h3 id="原生指训练图-不保证公开层表" tabindex="-1">原生指训练图，不保证公开层表 <a class="header-anchor" href="#原生指训练图-不保证公开层表" aria-label="Permalink to &quot;原生指训练图，不保证公开层表&quot;">​</a></h3><p>报告可复述的编码事实有限。视频：在长上下文里放<strong>均匀抽样的帧</strong>（视频理解实验常用 16 帧），帧可与文本、音频交错。音频：以 <strong>16 kHz</strong> 的 Universal Speech Model（USM）特征直接进入，而不是强制转写。分辨率可变，细粒度任务多花计算。图像输出走离散图像 token（DALL-E / Parti 谱系），理解侧不是必须经过同一套码本才能读图——报告没有把 Chameleon 式「单一稠密词表、无独立图像头」写成 Gemini 的实现约束。<a href="/llm/chameleon">Chameleon</a> 自己也指出：Gemini 更像早期融合加<strong>独立图像解码</strong>。</p><p><span class="marginnote">Nano-1/2 的 1.8B/3.25B 是报告里少数公开的参数量。不要给 Ultra 编层数或专家数。Gemma 声明继承 Gemini 研究，并不等于 Gemma 2B 的结构是 Ultra 的缩小版。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预训练数据：网页、书籍、代码，以及图像、音频、视频，多语。SentencePiece 在全部语料抽样上训词表，非拉丁文字切得更短。训练与推理走 TPU 与 Pathways 一类基础设施，报告不给出集群规模。后训练：SFT + RLHF，产品面分成 Gemini 应用与 Gemini API 两条，再混入专家整理的图文垂直数据。工具 / 扩展在内部旅行规划与视频发现偏好测试上，带工具的模型约 78% 轮次更受欢迎（排除平局）——这是产品叙事，不是多模态编码公式。</p><h3 id="评测口径必须拆开" tabindex="-1">评测口径必须拆开 <a class="header-anchor" href="#评测口径必须拆开" aria-label="Permalink to &quot;评测口径必须拆开&quot;">​</a></h3><p>文本：Ultra 的 MMLU <strong>90.04%</strong> 来自 uncertainty-routed CoT（多样本思维链，共识过阈值才投票，否则回退贪心）；标准 5-shot 约 <strong>83.7%</strong>。把 90 写成「5-shot 已经专家级」是错引。多模态：MMMU <strong>62.4%</strong>（当时相对前一最佳约 +5 分）。视频：少样本 caption 与零样本 QA，YouTube 类集合按 2023 年 11 月仍公开的视频评。音频：Pro 在 ASR/AST 上对照 USM 与 Whisper；FLEURS 训练集聚过的要单独声明，去掉 FLEURS 后 Pro 仍可报一个 WER。Nano-1 在多数 ASR 集上超过 Whisper，这是端侧档的主张。</p>',13)),(e(),s(E,null,{default:t(()=>[h(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20SEQ%5B%22%E4%BA%A4%E9%94%99%E8%BE%93%E5%85%A5%E5%BA%8F%E5%88%97%2032K%22%5D%0A%20%20I%5B%22%E5%9B%BE%E5%83%8F%20%2F%20%E5%B8%A7%20%E5%8F%AF%E5%8F%98%E5%88%86%E8%BE%A8%E7%8E%87%22%5D%20--%3E%20SEQ%0A%20%20A%5B%22%E9%9F%B3%E9%A2%91%2016kHz%20USM%20%E7%89%B9%E5%BE%81%22%5D%20--%3E%20SEQ%0A%20%20SEQ%20--%3E%20G%5B%22%E5%8E%9F%E7%94%9F%E5%A4%9A%E6%A8%A1%E6%80%81%20Transformer%22%5D%0A%20%20G%20--%3E%20OT%5B%22%E6%96%87%E6%9C%AC%22%5D%0A%20%20G%20--%3E%20OI%5B%22%E7%A6%BB%E6%95%A3%E5%9B%BE%E5%83%8F%20token%22%5D%0A%20%20OI%20--%3E%20PIX%5B%22%E5%9B%BE%E5%83%8F%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>联合训练让同一套参数在图、声、字上共享表示：物理卷上的手写推导可以和符号推理用同一套激活，而不经过「先 OCR 成字、再当纯文本题」的硬接口。交错序列提供时间与模态的共同位置轴——烹饪示例里口播问题与灶台照片交替，模型要在音频里听问题、在图像里看熟度。视频理解被收成「帧的时间序列 + 文本」，16 帧是评测协议不是光学上限。离散图像 token 使出图与写字可以交错，但独立解码器意味着生成图像不必与理解编码器共享量化误差，这与 Chameleon 的单一码本不同。</p><p>32K 的机制用合成检索（键值埋在上下文头、长填充后询问）和长文档 NLL 随位置下降来辩护：Ultra 全窗取值约 98% 准确。这只说明窗口被用到，不说明视频以帧计可以无损塞满 32K。</p><h3 id="和适配器派、和-1-5" tabindex="-1">和适配器派、和 1.5 <a class="header-anchor" href="#和适配器派、和-1-5" aria-label="Permalink to &quot;和适配器派、和 1.5&quot;">​</a></h3><p>LLaVA / IDEFICS2 是强单模态骨干的后融合；报告把原生写成从零联合，不提供可复现的 token 配比。1.5 把上下文拉到百万级并引入稀疏专家，用来解决「32K 装不下小时视频 / 代码库」；那是另一篇报告的对象。不要用 1.5 Flash 的延迟表解释 1.0 Ultra 的 MMMU。</p><p><span class="marginnote">「20 项多模态基准全部 SOTA」是 1.0 报告自己的表，含内部与外部集、含不同 shot。对外引用应落到 MMMU、具体视频集、具体 ASR 集，并写 shot 与日期。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>层表、数据配比、图像 tokenizer 细节未公开，工程上不能「按论文复现 Ultra」。原生多模态不自动等于开源权重。安全与责任章节是部署约束：图到文、视频到文的影响评估走内部流程，不能当架构消融。音频 16 kHz 特征仍是前端选择，麦克风阵列与说话人分离不在报告里。视频 16 帧协议会错过短时动作；产品抽帧策略与论文评测可以不同，不能把基准分数写成直播理解。</p><p>Nano 的 4-bit 与蒸馏是端侧故事，与 Ultra 的专家考试叙事不要写在同一张容量表。出图质量与理解质量可以脱节，因为解码器独立。工具 78% 偏好是内部集，不是 Arena。</p><p><span class="marginnote">出处：Gemini Team，<em>Gemini: A Family of Highly Capable Multimodal Models</em>，arXiv:2312.11805。基础设施背景可指向 Pathways（Barham 等）与 USM（Zhang 等 2023），不要编造未公开的 TPU 拓扑。1.5 报告 arXiv:2403.05530 不得用来改写 1.0 的 32K 与三档定义。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Gemini 1.0 主张从零联合训练文本、图像、音频、视频，家族为 Ultra / Pro / Nano，窗口 32K。</li><li>视频按帧交错，音频走 16 kHz USM 特征；出图用离散图像 token 加独立解码器。</li><li>MMLU 90.04% 是 routed CoT，不是默认 5-shot；MMMU 62.4% 是当时多模态推理主数字。</li><li>原生指训练与交错接口，不提供可复现层表；与适配器派、与 Chameleon 单码本都不同。</li><li>出处：Gemini Team，arXiv:2312.11805。</li></ul>',12))])}const P=n(p,[["render",d]]);export{_ as __pageData,P as default};
